// Contract test for the deterministic instance counter
// (scripts/drawing-ocr/instance_counter.py). The fixture is generated by
// that counter from a made-up layout (see synthetic_fixture() in
// scripts/drawing-ocr/test_instance_core.py, which also fails if this
// fixture drifts from the counter). It proves the counter's two outputs fit
// the app's EXISTING contracts unchanged: count items parse as
// cunstruct.analysis.v1, instances parse as cunstruct.observation.v1, and the
// existing Type -> Instances mapping and reconciliation rule read them as
// intended. Synthetic layout only — not evidence of accuracy on real drawings.
import { describe, it, expect } from "vitest";
import fixture from "./__fixtures__/instanceCounterSynthetic.json";
import { parseAnalysisV1 } from "./analysisSchemaV1";
import { parseObservationsV1 } from "./observationSchemaV1";
import { physicalInstancesForType, hasScheduleEntryForType } from "./typeInstances";
import { reconcileInstances } from "./instanceReconciliation";
import { isCountableUnit } from "./typeGrouping";
import type { LocationObservation } from "./locationObservations";

const analysis = parseAnalysisV1(JSON.stringify(fixture.analysis));
const parsedObs = parseObservationsV1(JSON.stringify(fixture.observations));
const observations: LocationObservation[] = (parsedObs.observations ?? []).map((o, i) => ({
  id: `obs-${i}`,
  observationType: o.observationType,
  mark: o.mark ?? null,
  scopeHint: o.scopeHint ?? null,
  locationText: o.locationText ?? null,
  attributes: o.attributes,
  evidence: o.source,
  evidenceCompleteness: o.evidenceCompleteness,
  createdAt: "2026-01-01T00:00:00Z",
}));
const item = (key: string) => analysis.analysis!.items.find((i) => i.key === key)!;

function status(key: string) {
  const it = item(key);
  return reconcileInstances({
    countable: isCountableUnit(it.unit),
    expectedQuantity: it.quantity,
    locationRan: true,
    physicalLocatedCount: physicalInstancesForType({ key: it.key }, observations).length,
    hasScheduleEntry: hasScheduleEntryForType({ key: it.key }, observations),
    hasEvidence: (it.source?.evidence.length ?? 0) > 0,
    criticalReasons: [],
    explicitlyFlagged: false,
  });
}

describe("instance counter output vs the app's existing contracts", () => {
  it("parses as analysis.v1 and observation.v1 with no warnings or rejections", () => {
    expect(analysis.ok).toBe(true);
    expect(analysis.warnings).toEqual([]);
    expect(parsedObs.ok).toBe(true);
    expect(parsedObs.warnings).toEqual([]);
    expect(parsedObs.diagnostics?.rejected).toEqual([]);
  });

  it("keys count items by mark, so the existing Type -> Instances mapping finds each instance", () => {
    expect(item("D1")).toMatchObject({ quantity: 2, unit: "nr", aiStatus: "MEASURED" });
    expect(physicalInstancesForType({ key: "D1" }, observations)).toHaveLength(2);
    // schedule rows are schedule_entry observations: documented, never counted as placed units
    expect(hasScheduleEntryForType({ key: "W2" }, observations)).toBe(true);
    expect(physicalInstancesForType({ key: "W2" }, observations)).toHaveLength(0);
  });

  it("a resolved count with a schedule entry reconciles GREEN; unresolved counts stay unresolved", () => {
    expect(status("D1")).toBe("GREEN");
    // W1: one tag held on a view boundary -> PENDING with lower/upper candidates, never a guessed number
    expect(item("W1")).toMatchObject({ quantity: null, aiStatus: "PENDING" });
    expect(item("W1").candidates?.map((c) => c.value).sort()).toEqual([1, 2]);
    expect(status("W1")).toBe("RED");
    // W2: scheduled, never found on a plan
    expect(item("W2")).toMatchObject({ quantity: null, aiStatus: "PENDING" });
    expect(status("W2")).toBe("RED");
  });

  it("reports an untagged opening symbol as a review item with its evidence box", () => {
    const flag = analysis.analysis!.items.find((i) => i.key.startsWith("FLAG:untagged"))!;
    expect(flag).toMatchObject({ quantity: null, aiStatus: "PENDING" });
    expect(flag.source?.evidence[0].bbox).toEqual([230, 180, 260, 210]);
  });
});
